CREATE TEMP TABLE s503c_cards (id bigint, s_ed text, s_book text, src_ch int, src_vn int, src_text text, t_ed text, tgt_book text, tgt_ch int, tgt_vn int, old_note text, new_note text, thread_id bigint, old_mnote text, new_mnote text) ON COMMIT DROP;
INSERT INTO s503c_cards VALUES
(6784,'canon','luke',10,1,$n$After these things the Lord appointed other seventy also, and sent them two and two before his face into every city and place, whither he himself would come.$n$,'canon','genesis',10,32,$n$thread:the-seventy-sent-out-as-yasharel-numbered-against-the-seventy-nations | *Yahuah (the Lord) appointed other seventy also, and sent them two and two.* The number traces directly to Bereshit (Genesis) 10:32's Table of Nations: *These are the families of the sons of Noach (Noah), after their generations, in their nations: and by these were the nations divided in the earth after the flood.* The Genesis 10 list contains seventy peoples — the numbering of the Most High at the dispersion. The King's seventy sent out is a one-for-one Yashar'el-contingent answer.$n$,$n$Genesis 10:32 — *These are the families of the sons of Noah, after their generations, in their nations: and by these were the nations divided in the earth after the flood.* *After these things the Lord appointed other seventy also, and sent them two and two before his face into every city and place, whither he himself would come.* (Luke 10:1) Yahusha (Jesus) sends out seventy, and the number was counted long before. Genesis lists the families of Noah's sons, and by them *the nations divided* after the flood. Those families come to seventy. The seventy he sends are numbered against the nations they are sent into.$n$,558,$n$*Yahuah (the Lord) appointed other seventy also, and sent them two and two.* The number traces directly to Bereshit (Genesis) 10:32's Table of Nations: *These are the families of the sons of Noach (Noah), after their generations, in their nations: and by these were the nations divided in the earth after the flood.* The Genesis 10 list contains seventy peoples — the numbering of the Most High at the dispersion. The King's seventy sent out is a one-for-one Yashar'el-contingent answer.$n$,$n$Genesis 10:32 — *by these were the nations divided in the earth after the flood.* The nations divided after the flood came to seventy families, and that is the count the seventy sent out are set against.$n$),
(6782,'canon','luke',10,1,$n$After these things the Lord appointed other seventy also, and sent them two and two before his face into every city and place, whither he himself would come.$n$,'canon','genesis',46,27,$n$thread:the-seventy-sent-out-as-yasharel-numbered-against-the-seventy-nations | *All the souls of the house of Ya'aqov (Jacob), which came into Egypt, were threescore and ten.* The seventy-sons-of-Yashar'el at the entry into Egypt is the covenant-side mirror to the seventy-nations of Bereshit (Genesis) 10. The seventy sent out is Yashar'el's twelve-tribe-and-seventy-elder constitution at the start of the gathering.$n$,$n$Genesis 46:27 — *And the sons of Joseph, which were born him in Egypt, were two souls: all the souls of the house of Jacob, which came into Egypt, were threescore and ten.* *After these things the Lord appointed other seventy also, and sent them two and two before his face into every city and place, whither he himself would come.* (Luke 10:1) Seventy again, this time the house of Jacob going down. The two sons born to Joseph in Egypt bring the count to *threescore and ten*, and that is the whole house that came in. The seventy Yahusha (Jesus) sends is the house's number, set beside the number of the nations.$n$,558,$n$*All the souls of the house of Ya'aqov (Jacob), which came into Egypt, were threescore and ten.* The seventy-sons-of-Yashar'el at the entry into Egypt is the covenant-side mirror to the seventy-nations of Bereshit (Genesis) 10. The seventy sent out is Yashar'el's twelve-tribe-and-seventy-elder constitution at the start of the gathering.$n$,$n$Genesis 46:27 — *all the souls of the house of Jacob, which came into Egypt, were threescore and ten.* The house of Jacob went into Egypt at seventy, so the seventy sent out carry the number of the house.$n$),
(6781,'canon','luke',10,1,$n$After these things the Lord appointed other seventy also, and sent them two and two before his face into every city and place, whither he himself would come.$n$,'canon','exodus',1,5,$n$thread:the-seventy-sent-out-as-yasharel-numbered-against-the-seventy-nations | *And all the souls that came out of the loins of Ya'aqov (Jacob) were seventy souls.* The Shemot (Exodus) confirmation of the seventy-house-of-Ya'aqov number.$n$,$n$Exodus 1:5 — *And all the souls that came out of the loins of Jacob were seventy souls: for Joseph was in Egypt already.* *After these things the Lord appointed other seventy also, and sent them two and two before his face into every city and place, whither he himself would come.* (Luke 10:1) The count is told a second time and the number does not move. Every soul that came out of Jacob's loins was *seventy souls*, and Joseph was in Egypt already. The seventy sent before the face of Yahusha (Jesus) stand beside the house as it was numbered going down.$n$,558,$n$*And all the souls that came out of the loins of Ya'aqov (Jacob) were seventy souls.* The Shemot (Exodus) confirmation of the seventy-house-of-Ya'aqov number.$n$,$n$Exodus 1:5 — *all the souls that came out of the loins of Jacob were seventy souls.* Exodus gives the same number for the house of Jacob, confirming the seventy that the nations' seventy are set against.$n$),
(6780,'canon','luke',10,1,$n$After these things the Lord appointed other seventy also, and sent them two and two before his face into every city and place, whither he himself would come.$n$,'canon','numbers',11,16,$n$thread:the-seventy-sent-out-as-yasharel-numbered-against-the-seventy-nations | *Gather unto me seventy men of the elders of Yashar'el (Israel), whom thou knowest to be the elders of the people, and officers over them.* The seventy elders Mosheh (Moses) appoints under Yahuah's (the LORD's) own instruction — the seventy-Yashar'el structure repeating itself in the wilderness administration. The seventy sent out is the same Yashar'el-administrative-seventy walking into the Yashar'el-territory of the seventy nations.$n$,$n$Numbers 11:16 — *And Yahuah (LORD) said unto Moses, Gather unto me seventy men of the elders of Yashar'el (Israel), whom thou knowest to be the elders of the people, and officers over them; and bring them unto the tabernacle of the congregation, that they may stand there with thee.* *After these things the Lord appointed other seventy also, and sent them two and two before his face into every city and place, whither he himself would come.* (Luke 10:1) Moses is told to gather seventy of the elders and bring them to the tabernacle to stand with him. The number comes up a third time, now in the elders of the house. When Yahusha (Jesus) sends seventy before his face, it is that house numbered again, as it was in Egypt and in the wilderness.$n$,558,$n$*Gather unto me seventy men of the elders of Yashar'el (Israel), whom thou knowest to be the elders of the people, and officers over them.* The seventy elders Mosheh (Moses) appoints under Yahuah's (the LORD's) own instruction — the seventy-Yashar'el structure repeating itself in the wilderness administration. The seventy sent out is the same Yashar'el-administrative-seventy walking into the Yashar'el-territory of the seventy nations.$n$,$n$Numbers 11:16 — *Gather unto me seventy men of the elders of Yashar'el (Israel).* The seventy elders of Yashar'el (Israel) gathered under Moses are the house's number repeating, the number Luke's seventy carry.$n$),
(6783,'canon','luke',10,1,$n$After these things the Lord appointed other seventy also, and sent them two and two before his face into every city and place, whither he himself would come.$n$,'canon','deuteronomy',32,8,$n$thread:the-seventy-sent-out-as-yasharel-numbered-against-the-seventy-nations | *When the Most High divided to the nations their inheritance, when he separated the sons of Adam, he set the bounds of the people according to the number of the children of Yashar'el (Israel).* Devarim (Deuteronomy) 32:8 names the seventy-nations / seventy-sons-of-Yashar'el mirror (older Hebrew witness: *according to the number of the sons of Elohim*) — the seventy-fold register the King's seventy sent out walks.$n$,$n$Deuteronomy 32:8 — *When the El Elyon (most High) divided to the nations their inheritance, when he separated the sons of Adam, he set the bounds of the people according to the number of the children of Yashar'el (Israel).* *After these things the Lord appointed other seventy also, and sent them two and two before his face into every city and place, whither he himself would come.* (Luke 10:1) Moses sings that when the nations were divided, the bounds were set *according to the number* of a people. The oldest Hebrew copies read sons of Elohim (God) where the later copies read children of Yashar'el (Israel). Either way a number set the bounds, and Yahusha (Jesus) sends seventy, the house's number, into the cities of the nations.$n$,558,$n$*When the Most High divided to the nations their inheritance, when he separated the sons of Adam, he set the bounds of the people according to the number of the children of Yashar'el (Israel).* Devarim (Deuteronomy) 32:8 names the seventy-nations / seventy-sons-of-Yashar'el mirror (older Hebrew witness: *according to the number of the sons of Elohim*) — the seventy-fold register the King's seventy sent out walks.$n$,$n$Deuteronomy 32:8 — *he set the bounds of the people according to the number of the children of Yashar'el (Israel).* The bounds of the nations were set by a number, and the seventy sent out are that number going into those bounds.$n$),
(6779,'canon','luke',10,9,$n$And heal the sick that are therein, and say unto them, The kingdom of Elohim (God) is come nigh unto you.$n$,'canon','matthew',10,7,$n$thread:the-seventy-sent-out-as-yasharel-numbered-against-the-seventy-nations | *Heal the sick that are therein, and say unto them, The kingdom of Elohim (God) is come nigh unto you.* The seventy carry the same charge as the Twelve of Matthew 10 / Luke 9 — heal, proclaim. The Twelve correspond to the tribes; the seventy correspond to the elders; together the constitutional shape of Yashar'el is sent out before the King.$n$,$n$Matthew 10:7 — *And as ye go, preach, saying, The kingdom of heaven is at hand.* *And heal the sick that are therein, and say unto them, The kingdom of Elohim (God) is come nigh unto you.* (Luke 10:9) The seventy are given the word the twelve were given. The twelve preached that the kingdom was *at hand*, and the seventy say it has *come nigh unto you*. Same charge, same sick to heal, handed on to a second company sent out before Yahusha (Jesus).$n$,558,$n$*Heal the sick that are therein, and say unto them, The kingdom of Elohim (God) is come nigh unto you.* The seventy carry the same charge as the Twelve of Matthew 10 / Luke 9 — heal, proclaim. The Twelve correspond to the tribes; the seventy correspond to the elders; together the constitutional shape of Yashar'el is sent out before the King.$n$,$n$Matthew 10:7 — *And as ye go, preach, saying, The kingdom of heaven is at hand.* The twelve went out preaching that the kingdom was at hand, and the seventy go out with the same word.$n$),
(6778,'canon','luke',10,11,$n$Even the very dust of your city, which cleaves on us, we do wipe off against you: notwithstanding be you sure of this, that the kingdom of Elohim (God) is come nigh unto you.$n$,'canon','matthew',10,14,$n$thread:the-seventy-sent-out-as-yasharel-numbered-against-the-seventy-nations | *Even the very dust of your city, which cleaveth on us, we do wipe off against you.* The shake-the-dust-off rejection-response from Mosheh's (Moses's) wilderness law walking into the seventy's commission — we do not chase the nations into a worship they will not give per the framework's reading.$n$,$n$Matthew 10:14 — *And whosoever shall not receive you, nor hear your words, when ye depart out of that house or city, shake off the dust of your feet.* *Even the very dust of your city, which cleaves on us, we do wipe off against you: notwithstanding be you sure of this, that the kingdom of Elohim (God) is come nigh unto you.* (Luke 10:11) Both companies are told what to do where they are not heard. The twelve are to *shake off the dust of your feet*, and the seventy wipe off the very dust of the city. They do not chase anyone. They say the kingdom of Elohim (God) has come near, and they go on.$n$,558,$n$*Even the very dust of your city, which cleaveth on us, we do wipe off against you.* The shake-the-dust-off rejection-response from Mosheh's (Moses's) wilderness law walking into the seventy's commission — we do not chase the nations into a worship they will not give per the framework's reading.$n$,$n$Matthew 10:14 — *when ye depart out of that house or city, shake off the dust of your feet.* Those who will not receive the word get the dust shaken off, the same answer the twelve were given.$n$),
(6777,'canon','luke',10,18,$n$And he said unto them, I beheld Satan as lightning fall from heaven.$n$,'canon','revelation',12,9,$n$thread:the-seventy-sent-out-as-yasharel-numbered-against-the-seventy-nations | *I beheld ha-satan (Satan) as lightning fall from heaven.* The Watcher-rebellion answer the King names in seven words; ties to Revelation 12:7-9 where the dragon and his angels are cast out. The seventy's territory-by-territory undoing of unclean-spirit administration IS the working-out of the lightning-fall the King saw.$n$,$n$Revelation 12:9 — *And the great dragon was cast out, that old serpent, called the Devil, and Satan, which deceiveth the whole world: he was cast out into the earth, and his angels were cast out with him.* *And he said unto them, I beheld Satan as lightning fall from heaven.* (Luke 10:18) Yahusha (Jesus) says he beheld Satan fall like lightning from heaven. Revelation tells in its own words of the dragon, *that old serpent*, cast out into the earth with his angels. Set side by side, both speak of Satan brought down from heaven, and the seventy come back saying devils obey them.$n$,558,$n$*I beheld ha-satan (Satan) as lightning fall from heaven.* The Watcher-rebellion answer the King names in seven words; ties to Revelation 12:7-9 where the dragon and his angels are cast out. The seventy's territory-by-territory undoing of unclean-spirit administration IS the working-out of the lightning-fall the King saw.$n$,$n$Revelation 12:9 — *the great dragon was cast out, that old serpent, called the Devil, and Satan.* Revelation names the dragon as that old serpent called the Devil and Satan, cast out into the earth with his angels.$n$),
(6776,'canon','luke',10,19,$n$Behold, I give unto you power to tread on serpents and scorpions, and over all the power of the enemy: and nothing shall by any means hurt you.$n$,'canon','genesis',3,15,$n$thread:the-seventy-sent-out-as-yasharel-numbered-against-the-seventy-nations | *Behold, I give unto you power to tread on serpents and scorpions, and over all the power of the enemy.* The serpent-seed-war from Bereshit (Genesis) 3:15 walks forward — the seventy are handed authority over the serpent-administration that has held the nations since the dispersion.$n$,$n$Genesis 3:15 — *And I will put enmity between thee and the woman, and between thy seed and her seed; it shall bruise thy head, and thou shalt bruise his heel.* *Behold, I give unto you power to tread on serpents and scorpions, and over all the power of the enemy: and nothing shall by any means hurt you.* (Luke 10:19) The treading was promised in the garden. A serpent and a seed were set at enmity there, and the seed was to bruise the serpent's head. Now Yahusha (Jesus) gives the seventy power to tread on serpents and over *all the power of the enemy*, and that promise is what they walk out on.$n$,558,$n$*Behold, I give unto you power to tread on serpents and scorpions, and over all the power of the enemy.* The serpent-seed-war from Bereshit (Genesis) 3:15 walks forward — the seventy are handed authority over the serpent-administration that has held the nations since the dispersion.$n$,$n$Genesis 3:15 — *it shall bruise thy head, and thou shalt bruise his heel.* The serpent's head is to be bruised by the woman's seed, and the seventy are handed the treading that promise looked toward.$n$),
(6775,'canon','luke',10,21,$n$In that hour Yahusha (Jesus) rejoiced in spirit, and said, I thank you, O Father, the Lord of heaven and earth, that you have hid these things from the wise and prudent, and have revealed them unto babes: even so, Father; for so it seemed good in your sight.$n$,'canon','matthew',11,25,$n$thread:the-seventy-sent-out-as-yasharel-numbered-against-the-seventy-nations | *I thank thee, O Father, Lord of heaven and earth, that thou hast hid these things from the wise and prudent, and hast revealed them unto babes.* The synoptic-doublet of Matthew 11:25-27 lands in Luke's seventy-commissioning context — the cause-and-effect-of-hearing diagnostic the framework names: *thou hast hid* and *hast revealed* are sovereign-election-precedes-hearing language. Lord here is vocative-to-the-Father (preserve as *Lord* per S182 NT-Lord rule).$n$,$n$Matthew 11:25 — *At that time Yahusha (Jesus) answered and said, I thank thee, O Father, Yahuah (Lord) of heaven and earth, because thou hast hid these things from the wise and prudent, and hast revealed them unto babes.* *In that hour Yahusha (Jesus) rejoiced in spirit, and said, I thank you, O Father, the Lord of heaven and earth, that you have hid these things from the wise and prudent, and have revealed them unto babes: even so, Father; for so it seemed good in your sight.* (Luke 10:21) Yahusha (Jesus) gives the same thanks in Matthew and in Luke, and each time the Father hid and the Father revealed. The things are hid from *the wise and prudent* and shown to *babes*, so hearing is not a matter of cleverness. After the seventy return, those who hear them are the ones it was shown to.$n$,558,$n$*I thank thee, O Father, Lord of heaven and earth, that thou hast hid these things from the wise and prudent, and hast revealed them unto babes.* The synoptic-doublet of Matthew 11:25-27 lands in Luke's seventy-commissioning context — the cause-and-effect-of-hearing diagnostic the framework names: *thou hast hid* and *hast revealed* are sovereign-election-precedes-hearing language. Lord here is vocative-to-the-Father (preserve as *Lord* per S182 NT-Lord rule).$n$,$n$Matthew 11:25 — *thou hast hid these things from the wise and prudent, and hast revealed them unto babes.* The Father hides these things from the wise and shows them to babes, which is why some hear the seventy and some do not.$n$),
(6774,'canon','luke',10,22,$n$All things are delivered to me of my Father: and no man knows who the Son is, but the Father; and who the Father is, but the Son, and he to whom the Son will reveal him.$n$,'canon','john',10,14,$n$thread:the-seventy-sent-out-as-yasharel-numbered-against-the-seventy-nations | *No man knoweth who the Son is, but the Father; and who the Father is, but the Son, and he to whom the Son will reveal him.* The Formless-Father / Formed-Son revelation-economy named in the Markan / Matthean / Lukan doublet, paired with the Yochanan (John) 10:14-15 *I know my sheep, and am known of mine* — the same architecture of recognition running through every chapter.$n$,$n$John 10:14 — *I am the good shepherd, and know my sheep, and am known of mine.* *All things are delivered to me of my Father: and no man knows who the Son is, but the Father; and who the Father is, but the Son, and he to whom the Son will reveal him.* (Luke 10:22) The Son reveals the Father to whom he will, and here he says it from the shepherd's side. He knows his sheep and is *known of mine*. Those he shows himself to are his own sheep. In the cities the seventy enter, the ones it was shown to hear them, and the rest get the dust of their street.$n$,558,$n$*No man knoweth who the Son is, but the Father; and who the Father is, but the Son, and he to whom the Son will reveal him.* The Formless-Father / Formed-Son revelation-economy named in the Markan / Matthean / Lukan doublet, paired with the Yochanan (John) 10:14-15 *I know my sheep, and am known of mine* — the same architecture of recognition running through every chapter.$n$,$n$John 10:14 — *I am the good shepherd, and know my sheep, and am known of mine.* The shepherd knows his sheep and is known by them, which is the same showing and hearing the Son speaks of.$n$);
CREATE TEMP TABLE s503c_thread (id bigint, slug text, old_title text, new_title text, old_summary text, new_summary text) ON COMMIT DROP;
INSERT INTO s503c_thread VALUES (558, 'the-seventy-sent-out-as-yasharel-numbered-against-the-seventy-nations', $n$The seventy sent out — Yashar'el (Israel) numbered against the seventy nations of Bereshit (Genesis) 10$n$, $n$The seventy sent out two and two — the number of the nations, the number of Jacob's house, and the elders under Moses (Genesis 10; Deuteronomy 32; Numbers 11; Luke 10)$n$, $n$Luke alone carries this commissioning. *After these things Yahuah (the Lord) appointed other seventy also, and sent them two and two before his face into every city and place, whither he himself would come* (Luke 10:1). The number 70 is not arbitrary. Bereshit (Genesis) 10's Table of Nations lists seventy peoples descended from Noach (Noah)'s sons; Devarim (Deuteronomy) 32:8 names how *the Most High divided to the nations their inheritance, when he separated the sons of Adam, he set the bounds of the people according to the number of the children of Yashar'el (Israel)* — read in the older Hebrew witness as *according to the number of the sons of Elohim,* with the seventy-bnei-Elohim and the seventy-sons-of-Yashar'el (Genesis 46:27, Exodus 1:5) mirroring each other. The seventy sent out IS a Yashar'el-being-numbered-against-the-seventy-nations register: the King is sending out his Yashar'el-sized contingent to confront the territory the Watcher-administration has held since the dispersion of nations at the tower. The framework-major substance pours out across the chapter: the satan-falling-as-lightning vision (Luke 10:18) is the Watcher-rebellion answer; the hidden-from-the-wise-revealed-to-babes (Luke 10:21-22) is the cause-and-effect-of-hearing diagnostic in compressed form. FRAMEWORK-MAJOR.$n$, $n$It ain't new. Seventy is a counted number before Luke uses it. The nations after the flood, the house of Jacob going down into Egypt, and the elders Moses gathered to the tabernacle all come to seventy, and Luke alone tells of seventy sent out:

*After these things Yahusha (Lord) appointed other seventy also, and sent them two and two before his face into every city and place, whither he himself would come.* (Luke 10:1)

Count the nations first:

*These are the families of the sons of Noah, after their generations, in their nations: and by these were the nations divided in the earth after the flood.* (Genesis 10:32)

The families listed in that chapter come to seventy. Then count the house that went down into Egypt:

*And the sons of Joseph, which were born him in Egypt, were two souls: all the souls of the house of Jacob, which came into Egypt, were threescore and ten.* (Genesis 46:27)

*And all the souls that came out of the loins of Jacob were seventy souls: for Joseph was in Egypt already.* (Exodus 1:5)

Moses sings that the two numbers were set against each other on purpose, when the nations were divided after Babel:

*When the El Elyon (most High) divided to the nations their inheritance, when he separated the sons of Adam, he set the bounds of the people according to the number of the children of Yashar'el (Israel).* (Deuteronomy 32:8)

*For the LORD’S portion is his people; Jacob is the lot of his inheritance.* (Deuteronomy 32:9)

The oldest Hebrew copies of that verse read *sons of Elohim (God)* where the later copies read *children of Yashar'el (Israel)*; either way the bounds of the nations were set by a number, the number is Jacob's, and Jacob himself is the portion kept back. The nations went under other princes at the dividing, and scripture does not hide it:

*I have said, Ye are gods; and all of you are children of the El Elyon (most High).* (Psalm 82:6)

*But ye shall die like men, and fall like one of the princes.* (Psalm 82:7)

*Arise, O Elohim (God), judge the earth: for thou shalt inherit all nations.* (Psalm 82:8)

In the wilderness the number of the house repeats in its elders:

*And Yahuah (LORD) said unto Moses, Gather unto me seventy men of the elders of Yashar'el (Israel), whom thou knowest to be the elders of the people, and officers over them; and bring them unto the tabernacle of the congregation, that they may stand there with thee.* (Numbers 11:16)

So when Yahusha (Jesus) sends seventy before his face, it is the house numbered as it was numbered going into Egypt and under Moses, sent out into the cities the nations were given at the dividing, with the charge the twelve had:

*And heal the sick that are therein, and say unto them, The kingdom of Elohim (God) is come nigh unto you.* (Luke 10:9)

*Even the very dust of your city, which cleaveth on us, we do wipe off against you: notwithstanding be ye sure of this, that the kingdom of Elohim (God) is come nigh unto you.* (Luke 10:11)

When they come back he tells them what he saw while they went, and what they were given to do to the princes of those cities:

*And the seventy returned again with joy, saying, Adonai (Lord), even the devils are subject unto us through thy name.* (Luke 10:17)

*And he said unto them, I beheld Satan as lightning fall from heaven.* (Luke 10:18)

*Behold, I give unto you power to tread on serpents and scorpions, and over all the power of the enemy: and nothing shall by any means hurt you.* (Luke 10:19)

The serpent and the seed of the woman have been at enmity since the garden, and the treading was promised there:

*And I will put enmity between thee and the woman, and between thy seed and her seed; it shall bruise thy head, and thou shalt bruise his heel.* (Genesis 3:15)

Then he says why the thing is hidden from some and seen by others, and it is not their cleverness:

*In that hour Yahusha (Jesus) rejoiced in spirit, and said, I thank thee, O Father, Yahuah (Lord) of heaven and earth, that thou hast hid these things from the wise and prudent, and hast revealed them unto babes: even so, Father; for so it seemed good in thy sight.* (Luke 10:21)

*All things are delivered to me of my Father: and no man knoweth who the Son is, but the Father; and who the Father is, but the Son, and he to whom the Son will reveal him.* (Luke 10:22)

The Father hides and the Son reveals. The seventy go out as the house numbered against the nations, and in those cities the ones it was shown to hear them, and the ones it was hidden from get the dust of their own street.$n$);

DO $s503c$
DECLARE r record; x record; n int;
BEGIN
  FOR r IN SELECT * FROM s503c_cards LOOP
    SELECT xr.id, xr.note, sv.text AS stext, se.slug AS sed, sb.slug AS sbook, sc.chapter_number AS sch, sv.verse_number AS svn, te.slug AS ted, tb.slug AS tbook, tc.chapter_number AS tch, tv.verse_number AS tvn
      INTO x FROM cross_references xr
      JOIN verses sv ON sv.id = xr.source_verse_id JOIN chapters sc ON sc.id = sv.chapter_id JOIN books sb ON sb.id = sc.book_id JOIN editions se ON se.id = sb.edition_id
      JOIN verses tv ON tv.id = xr.target_verse_id JOIN chapters tc ON tc.id = tv.chapter_id JOIN books tb ON tb.id = tc.book_id JOIN editions te ON te.id = tb.edition_id
      WHERE xr.id = r.id;
    IF NOT FOUND THEN RAISE EXCEPTION 'S503c: card % is gone', r.id; END IF;
    IF x.sed <> r.s_ed OR x.sbook <> r.s_book OR x.sch <> r.src_ch OR x.svn <> r.src_vn OR x.ted <> r.t_ed OR x.tbook <> r.tgt_book OR x.tch <> r.tgt_ch OR x.tvn <> r.tgt_vn THEN
      RAISE EXCEPTION 'S503c: card % no longer sits on the verse pair this was written for', r.id; END IF;
    IF x.stext <> r.src_text THEN RAISE EXCEPTION 'S503c: live text of % %:% differs from the read-back — re-dump and rebuild', r.s_book, r.src_ch, r.src_vn; END IF;
    IF x.note IS DISTINCT FROM r.old_note AND x.note IS DISTINCT FROM r.new_note THEN RAISE EXCEPTION 'S503c: the live note of card % differs from the read-back — re-dump and rebuild', r.id; END IF;
    SELECT count(*) INTO n FROM cross_reference_thread_members m WHERE m.cross_reference_id = r.id AND m.thread_id = r.thread_id AND (m.member_note IS NOT DISTINCT FROM r.old_mnote OR m.member_note IS NOT DISTINCT FROM r.new_mnote);
    IF n <> 1 THEN RAISE EXCEPTION 'S503c: card % has no member row in thread % carrying the member note this was written against', r.id, r.thread_id; END IF;
  END LOOP;
  SELECT t.* INTO x FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id AND s.slug = t.slug;
  IF NOT FOUND THEN RAISE EXCEPTION 'S503c: thread 558 not found under its slug'; END IF;
  SELECT count(*) INTO n FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id
    WHERE (t.title = s.old_title AND t.summary_md = s.old_summary) OR (t.title = s.new_title AND t.summary_md = s.new_summary);
  IF n <> 1 THEN RAISE EXCEPTION 'S503c: thread 558 title/summary differ from the read-back — re-dump and rebuild'; END IF;
END $s503c$;

DO $s503c2$
DECLARE n_notes int; n_m int; n_t int; n_c int;
BEGIN
  SELECT count(*) INTO n_c FROM s503c_cards;
  UPDATE cross_references xr SET note = c.new_note FROM s503c_cards c WHERE xr.id = c.id AND xr.note IS NOT DISTINCT FROM c.old_note AND c.old_note IS DISTINCT FROM c.new_note;
  GET DIAGNOSTICS n_notes = ROW_COUNT;
  UPDATE cross_reference_thread_members m SET member_note = c.new_mnote FROM s503c_cards c WHERE m.cross_reference_id = c.id AND m.thread_id = c.thread_id AND m.member_note IS NOT DISTINCT FROM c.old_mnote AND c.old_mnote IS DISTINCT FROM c.new_mnote;
  GET DIAGNOSTICS n_m = ROW_COUNT;
  UPDATE cross_reference_threads t SET title = s.new_title, summary_md = s.new_summary FROM s503c_thread s WHERE t.id = s.id AND t.title = s.old_title AND t.summary_md = s.old_summary AND (s.old_title <> s.new_title OR s.old_summary <> s.new_summary);
  GET DIAGNOSTICS n_t = ROW_COUNT;
  RAISE NOTICE 'S503c (the-seventy-sent-out) summary: notes rewritten % / already there %; member notes rewritten % / already there %; thread rewritten % / already there %', n_notes, n_c - n_notes, n_m, n_c - n_m, n_t, 1 - n_t;
END $s503c2$;
COMMIT;
\echo 'session503c — the-seventy-sent-out done.'
